package com.yeyamo_mobile.api.commerce_service.persistence;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;import static com.yeyamo_mobile.api.commerce_service.domain.CommerceTypes.*;
@Entity @Table(name="commerce_commission_rules")public class CommissionRule{@Id public UUID id;@Column(name="partner_id")public String partnerId;@Enumerated(EnumType.STRING)@Column(name="product_type")public ProductType productType;public BigDecimal percentage;@Column(name="fixed_amount")public BigDecimal fixedAmount;@Column(name="maximum_amount")public BigDecimal maximumAmount;public String currency;@Column(name="rule_version")public int ruleVersion;@Column(name="effective_from")public Instant effectiveFrom;@Column(name="effective_until")public Instant effectiveUntil;public String status;@Column(name="created_at")public Instant createdAt;@PrePersist void c(){id=id==null?UUID.randomUUID():id;createdAt=Instant.now();}}
